macro_rules! debug_assert {
    ($expr:expr, $handler:expr, $($arg:expr),*) => {
        if !$expr {
            $handler.handle(
                DEBUG_ASSERT_CUR_SOURCE_LOCATION!(),
                stringify!($expr),
                format_args!($($arg),*)
            )
        }
    };
}

#[macro_export]
macro_rules! debug_unreachable {
    ($handler:expr, $($arg:expr),*) => {{
        $handler.handle(
            DEBUG_ASSERT_CUR_SOURCE_LOCATION!(),
            "",
            format_args!($($arg),*)
        );
        process::abort();
    }};
}

